#include <stdio.h>
int fact(int n) {
    if (n <= 1) return 1;
    return n * fact(n - 1);
}
int main(void) {
    printf("%d\n", fact(5));
    return 0;
}

#include <stdio.h>
int sum(int n) {
    if (n == 0) return 0;
    return n + sum(n - 1);
}
int main(void) {
    printf("%d\n", sum(4));
    return 0;
}

#include <stdio.h>
void count(int n) {
    if (n == 0) return;
    count(n - 1);
    printf("%d ", n);
}
int main(void) {
    count(3);
    return 0;
}

#include <stdio.h>
int lenRec(const char *s, int i) {
    if (s[i] == '\0') return 0;
    return 1 + lenRec(s, i + 1);
}
int main(void) {
    printf("%d\n", lenRec("atom", 0));
    return 0;
}

#include <stdio.h>
int ack(int m, int n) {
    if (m == 0) return n + 1;
    if (n == 0) return ack(m - 1, 1);
    return ack(m - 1, ack(m, n - 1));
}
int main(void) {
    printf("%d\n", ack(2, 3));
    return 0;
}

#include <stdio.h>
#include <string.h>
int isPalin(const char *s, int lo, int hi) {
    if (lo >= hi) return 1;
    if (s[lo] != s[hi]) return 0;
    return isPalin(s, lo + 1, hi - 1);
}
int main(void) {
    char s[] = "racecar";
    printf("%d\n", isPalin(s, 0, (int)strlen(s) - 1));
    return 0;
}

#include <stdio.h>
int f(int n) {
    if (n > 100) return n - 10;
    return f(f(n + 11));
}
int main(void) {
    printf("%d\n", f(95));
    return 0;
}

#include <stdio.h>
static inline int square(int x) { return x * x; }
int main(void) {
    int a = 5;
    printf("%d\n", square(a + 1));
    return 0;
}
